import{_ as d,o as e,c as o,a2 as c}from"./chunks/framework.Ch4PdLd_.js";const u=JSON.parse('{"title":"快捷键","description":"","frontmatter":{},"headers":[],"relativePath":"reference/keybindings.md","filePath":"reference/keybindings.md"}'),r={name:"reference/keybindings.md"};function a(i,t,l,s,n,p){return e(),o("div",null,[...t[0]||(t[0]=[c(`<h1 id="快捷键" tabindex="-1">快捷键 <a class="header-anchor" href="#快捷键" aria-label="Permalink to &quot;快捷键&quot;">​</a></h1><p>nek 的快捷键绑定在一个个命名的<strong>动作</strong>上（例如 <code>app.session.new</code>）。你可以修改默认绑定，或给没有默认按键的动作绑定按键。</p><p>在 nek 里运行 <code>/hotkeys</code> 查看输入框和应用当前生效的快捷键。</p><h2 id="assign" tabindex="-1">修改快捷键 <a class="header-anchor" href="#assign" aria-label="Permalink to &quot;修改快捷键 {#assign}&quot;">​</a></h2><p>创建 <code>~/.nek/agent/keybindings.json</code>，把动作 ID 映射到一个按键或按键列表：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;app.session.new&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ctrl+shift+n&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;app.session.tree&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ctrl+shift+t&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;alt+shift+t&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>配置的值<strong>替换</strong>该动作的默认绑定。用空列表禁用一个动作的所有按键：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;tui.altScreen.pageUp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: []</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>修改后运行 <code>/reload</code> 应用到当前会话。</p><p>切换 Plan 模式的快捷键（默认 <code>alt+m</code>）不在这里，而在 <a href="/nekcode/reference/nek-yaml">nek.yaml</a> 的 <code>plan.shortcut</code>。</p><h2 id="syntax" tabindex="-1">按键写法 <a class="header-anchor" href="#syntax" aria-label="Permalink to &quot;按键写法 {#syntax}&quot;">​</a></h2><p>格式为 <code>修饰键+键</code>。修饰键有 <code>ctrl</code>、<code>shift</code>、<code>alt</code>、<code>super</code>，可以组合使用。可用的键：</p><ul><li><strong>字母</strong>：<code>a</code>-<code>z</code></li><li><strong>数字</strong>：<code>0</code>-<code>9</code></li><li><strong>特殊键</strong>：<code>escape</code>、<code>esc</code>、<code>enter</code>、<code>return</code>、<code>tab</code>、<code>space</code>、<code>backspace</code>、<code>delete</code>、<code>insert</code>、<code>clear</code>、<code>home</code>、<code>end</code>、<code>pageUp</code>、<code>pageDown</code>、<code>up</code>、<code>down</code>、<code>left</code>、<code>right</code></li><li><strong>功能键</strong>：<code>f1</code>-<code>f12</code></li><li><strong>符号</strong>：<code>\`</code>、<code>-</code>、<code>=</code>、<code>[</code>、<code>]</code>、<code>\\</code>、<code>;</code>、<code>&#39;</code>、<code>,</code>、<code>.</code>、<code>/</code>、<code>!</code>、<code>@</code>、<code>#</code>、<code>$</code>、<code>%</code>、<code>^</code>、<code>&amp;</code>、<code>*</code>、<code>(</code>、<code>)</code>、<code>_</code>、<code>+</code>、<code>|</code>、<code>~</code>、<code>{</code>、<code>}</code>、<code>:</code>、<code>&lt;</code>、<code>&gt;</code>、<code>?</code></li></ul><p>例如：<code>ctrl+shift+x</code>、<code>alt+ctrl+x</code>、<code>ctrl+shift+alt+x</code>、<code>super+k</code>、<code>ctrl+super+k</code>、<code>ctrl+1</code>。</p><p><code>super</code> 组合需要终端单独上报这个修饰键（通常通过 Kitty 键盘协议），不支持的终端里可能无效。</p><h2 id="输入框" tabindex="-1">输入框 <a class="header-anchor" href="#输入框" aria-label="Permalink to &quot;输入框&quot;">​</a></h2><h3 id="光标移动" tabindex="-1">光标移动 <a class="header-anchor" href="#光标移动" aria-label="Permalink to &quot;光标移动&quot;">​</a></h3><table tabindex="0"><thead><tr><th>动作 ID</th><th>默认按键</th><th>说明</th></tr></thead><tbody><tr><td><code>tui.editor.cursorUp</code></td><td><code>up</code></td><td>光标上移；在首行时浏览更早的历史</td></tr><tr><td><code>tui.editor.cursorDown</code></td><td><code>down</code></td><td>光标下移；在末行时浏览更新的历史</td></tr><tr><td><code>tui.editor.historyPrevious</code></td><td>无</td><td>上一条历史提示词（不论光标位置）</td></tr><tr><td><code>tui.editor.historyNext</code></td><td>无</td><td>下一条历史提示词</td></tr><tr><td><code>tui.editor.cursorLeft</code></td><td><code>left</code>、<code>ctrl+b</code></td><td>左移</td></tr><tr><td><code>tui.editor.cursorRight</code></td><td><code>right</code>、<code>ctrl+f</code></td><td>右移</td></tr><tr><td><code>tui.editor.cursorWordLeft</code></td><td><code>alt+left</code>、<code>ctrl+left</code>、<code>alt+b</code></td><td>左移一个词</td></tr><tr><td><code>tui.editor.cursorWordRight</code></td><td><code>alt+right</code>、<code>ctrl+right</code>、<code>alt+f</code></td><td>右移一个词</td></tr><tr><td><code>tui.editor.cursorLineStart</code></td><td><code>home</code>、<code>ctrl+home</code>、<code>ctrl+a</code></td><td>到行首</td></tr><tr><td><code>tui.editor.cursorLineEnd</code></td><td><code>end</code>、<code>ctrl+end</code>、<code>ctrl+e</code></td><td>到行尾</td></tr><tr><td><code>tui.editor.jumpForward</code></td><td><code>ctrl+]</code></td><td>向前跳到指定字符</td></tr><tr><td><code>tui.editor.jumpBackward</code></td><td><code>ctrl+alt+]</code></td><td>向后跳到指定字符</td></tr><tr><td><code>tui.editor.pageUp</code></td><td><code>pageUp</code>、<code>ctrl+pageUp</code></td><td>向上翻页</td></tr><tr><td><code>tui.editor.pageDown</code></td><td><code>pageDown</code>、<code>ctrl+pageDown</code></td><td>向下翻页</td></tr></tbody></table><p>专用的历史动作优先于使用相同按键的应用动作。</p><h3 id="文本编辑" tabindex="-1">文本编辑 <a class="header-anchor" href="#文本编辑" aria-label="Permalink to &quot;文本编辑&quot;">​</a></h3><table tabindex="0"><thead><tr><th>动作 ID</th><th>默认按键</th><th>说明</th></tr></thead><tbody><tr><td><code>tui.editor.deleteCharBackward</code></td><td><code>backspace</code></td><td>向后删除一个字符</td></tr><tr><td><code>tui.editor.deleteCharForward</code></td><td><code>delete</code>、<code>ctrl+d</code></td><td>向前删除一个字符</td></tr><tr><td><code>tui.editor.deleteWordBackward</code></td><td><code>ctrl+w</code>、<code>alt+backspace</code></td><td>向后删除一个词</td></tr><tr><td><code>tui.editor.deleteWordForward</code></td><td><code>alt+d</code>、<code>alt+delete</code></td><td>向前删除一个词</td></tr><tr><td><code>tui.editor.deleteToLineStart</code></td><td><code>ctrl+u</code></td><td>删除到行首</td></tr><tr><td><code>tui.editor.deleteToLineEnd</code></td><td><code>ctrl+k</code></td><td>删除到行尾</td></tr><tr><td><code>tui.editor.yank</code></td><td><code>ctrl+y</code></td><td>粘贴最近删除的文本</td></tr><tr><td><code>tui.editor.yankPop</code></td><td><code>alt+y</code></td><td>粘贴后循环切换更早删除的文本</td></tr><tr><td><code>tui.editor.undo</code></td><td><code>ctrl+-</code>（Windows 为 <code>ctrl+z</code>，WSL 为 <code>alt+z</code>）</td><td>撤销</td></tr></tbody></table><h3 id="输入与选择" tabindex="-1">输入与选择 <a class="header-anchor" href="#输入与选择" aria-label="Permalink to &quot;输入与选择&quot;">​</a></h3><table tabindex="0"><thead><tr><th>动作 ID</th><th>默认按键</th><th>说明</th></tr></thead><tbody><tr><td><code>tui.input.newLine</code></td><td><code>shift+enter</code>、<code>ctrl+j</code></td><td>换行</td></tr><tr><td><code>tui.input.submit</code></td><td><code>enter</code></td><td>发送</td></tr><tr><td><code>tui.input.tab</code></td><td><code>tab</code></td><td>Tab 或补全</td></tr><tr><td><code>tui.input.copy</code></td><td><code>ctrl+c</code></td><td>复制选中内容</td></tr><tr><td><code>tui.select.up</code></td><td><code>up</code></td><td>列表中上移</td></tr><tr><td><code>tui.select.down</code></td><td><code>down</code></td><td>列表中下移</td></tr><tr><td><code>tui.select.pageUp</code></td><td><code>pageUp</code></td><td>列表中上翻页</td></tr><tr><td><code>tui.select.pageDown</code></td><td><code>pageDown</code></td><td>列表中下翻页</td></tr><tr><td><code>tui.select.confirm</code></td><td><code>enter</code></td><td>确认选择</td></tr><tr><td><code>tui.select.cancel</code></td><td><code>escape</code>、<code>ctrl+c</code></td><td>取消选择</td></tr></tbody></table><h2 id="全屏模式" tabindex="-1">全屏模式 <a class="header-anchor" href="#全屏模式" aria-label="Permalink to &quot;全屏模式&quot;">​</a></h2><p>全屏模式下这些动作控制对话记录，优先于使用相同按键的输入框动作。</p><table tabindex="0"><thead><tr><th>动作 ID</th><th>默认按键</th><th>说明</th></tr></thead><tbody><tr><td><code>tui.altScreen.pageUp</code></td><td><code>pageUp</code></td><td>对话向上翻一页</td></tr><tr><td><code>tui.altScreen.pageDown</code></td><td><code>pageDown</code></td><td>对话向下翻一页</td></tr><tr><td><code>tui.altScreen.halfPageUp</code></td><td>无</td><td>向上翻半页</td></tr><tr><td><code>tui.altScreen.halfPageDown</code></td><td>无</td><td>向下翻半页</td></tr><tr><td><code>tui.altScreen.lineUp</code></td><td>无</td><td>向上一行</td></tr><tr><td><code>tui.altScreen.lineDown</code></td><td>无</td><td>向下一行</td></tr><tr><td><code>tui.altScreen.previousPrompt</code></td><td><code>ctrl+shift+up</code>、<code>ctrl+up</code>（<code>ctrl+up</code> 仅 Windows/WSL）</td><td>跳到上一条标记的消息</td></tr><tr><td><code>tui.altScreen.nextPrompt</code></td><td><code>ctrl+shift+down</code>、<code>ctrl+down</code>（<code>ctrl+down</code> 仅 Windows/WSL）</td><td>跳到下一条标记的消息</td></tr><tr><td><code>tui.altScreen.search</code></td><td><code>ctrl+shift+f</code>（Windows/WSL 为 <code>ctrl+f</code>）</td><td>搜索对话记录</td></tr><tr><td><code>tui.altScreen.searchNext</code></td><td><code>enter</code>、<code>ctrl+g</code></td><td>搜索时跳到下一个匹配</td></tr><tr><td><code>tui.altScreen.searchPrevious</code></td><td><code>shift+enter</code>、<code>ctrl+shift+g</code></td><td>搜索时跳到上一个匹配</td></tr><tr><td><code>tui.altScreen.searchClose</code></td><td><code>escape</code></td><td>关闭搜索</td></tr><tr><td><code>tui.altScreen.top</code></td><td><code>home</code></td><td>滚动到对话开头</td></tr><tr><td><code>tui.altScreen.bottom</code></td><td><code>end</code></td><td>滚动到末尾并跟随新输出</td></tr></tbody></table><h2 id="应用" tabindex="-1">应用 <a class="header-anchor" href="#应用" aria-label="Permalink to &quot;应用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>动作 ID</th><th>默认按键</th><th>说明</th></tr></thead><tbody><tr><td><code>app.interrupt</code></td><td><code>escape</code></td><td>取消 / 中止</td></tr><tr><td><code>app.clear</code></td><td><code>ctrl+c</code></td><td>第一次清空输入框，第二次退出</td></tr><tr><td><code>app.exit</code></td><td><code>ctrl+d</code></td><td>输入框为空时退出</td></tr><tr><td><code>app.suspend</code></td><td><code>ctrl+z</code>（Windows 无）</td><td>挂起到后台</td></tr><tr><td><code>app.editor.external</code></td><td><code>ctrl+g</code></td><td>在外部编辑器中编辑（<code>externalEditor</code>、<code>$VISUAL</code>、<code>$EDITOR</code>，Windows 默认记事本，其他系统默认 <code>nano</code>）</td></tr><tr><td><code>app.clipboard.pasteImage</code></td><td><code>ctrl+v</code>（Windows/WSL 为 <code>alt+v</code>）</td><td>从剪贴板粘贴图片或文字</td></tr></tbody></table><p>原生 Windows 上 <code>app.suspend</code> 没有默认按键，因为 Windows 终端不支持 Unix 作业控制。手动绑定后 nek 只会显示一条状态信息而不会挂起。WSL 使用正常的 <code>ctrl+z</code> 和 <code>fg</code>。</p><h2 id="会话" tabindex="-1">会话 <a class="header-anchor" href="#会话" aria-label="Permalink to &quot;会话&quot;">​</a></h2><table tabindex="0"><thead><tr><th>动作 ID</th><th>默认按键</th><th>说明</th></tr></thead><tbody><tr><td><code>app.session.new</code></td><td>无</td><td>新会话（<code>/new</code>）</td></tr><tr><td><code>app.session.tree</code></td><td>无</td><td>打开会话树（<code>/tree</code>）</td></tr><tr><td><code>app.session.fork</code></td><td>无</td><td>分叉会话（<code>/fork</code>）</td></tr><tr><td><code>app.session.resume</code></td><td>无</td><td>打开会话列表（<code>/resume</code>）</td></tr><tr><td><code>app.session.togglePath</code></td><td><code>ctrl+p</code></td><td>会话列表中显示/隐藏路径</td></tr><tr><td><code>app.session.toggleSort</code></td><td><code>ctrl+s</code></td><td>会话列表中切换排序</td></tr><tr><td><code>app.session.toggleNamedFilter</code></td><td><code>ctrl+n</code></td><td>会话列表中只看已命名的会话</td></tr><tr><td><code>app.session.rename</code></td><td><code>ctrl+r</code></td><td>重命名会话</td></tr><tr><td><code>app.session.delete</code></td><td><code>ctrl+d</code></td><td>删除会话</td></tr><tr><td><code>app.session.deleteNoninvasive</code></td><td><code>ctrl+backspace</code></td><td>搜索框为空时删除会话</td></tr></tbody></table><h2 id="模型与思考" tabindex="-1">模型与思考 <a class="header-anchor" href="#模型与思考" aria-label="Permalink to &quot;模型与思考&quot;">​</a></h2><table tabindex="0"><thead><tr><th>动作 ID</th><th>默认按键</th><th>说明</th></tr></thead><tbody><tr><td><code>app.model.select</code></td><td><code>ctrl+l</code></td><td>打开模型选择器</td></tr><tr><td><code>app.model.cycleForward</code></td><td><code>ctrl+p</code></td><td>下一个模型</td></tr><tr><td><code>app.model.cycleBackward</code></td><td><code>shift+ctrl+p</code>（Windows/WSL 为 <code>alt+p</code>）</td><td>上一个模型</td></tr><tr><td><code>app.models.save</code></td><td><code>ctrl+s</code></td><td>把选中的默认模型或循环范围保存到设置</td></tr><tr><td><code>app.thinking.cycle</code></td><td><code>shift+tab</code></td><td>循环切换思考等级</td></tr><tr><td><code>app.thinking.save</code></td><td><code>ctrl+s</code></td><td>把当前思考等级保存到设置</td></tr><tr><td><code>app.thinking.toggle</code></td><td><code>ctrl+t</code></td><td>折叠/展开思考内容</td></tr></tbody></table><h2 id="显示与消息队列" tabindex="-1">显示与消息队列 <a class="header-anchor" href="#显示与消息队列" aria-label="Permalink to &quot;显示与消息队列&quot;">​</a></h2><table tabindex="0"><thead><tr><th>动作 ID</th><th>默认按键</th><th>说明</th></tr></thead><tbody><tr><td><code>app.tools.expand</code></td><td><code>ctrl+o</code></td><td>折叠/展开工具输出</td></tr><tr><td><code>app.message.copy</code></td><td><code>ctrl+x</code></td><td><code>/tree</code> 中复制选中的消息；全屏模式下 <code>fullscreenCopyOnSelect</code> 为 <code>false</code> 时复制当前选区；其他情况复制最后一条助手消息</td></tr><tr><td><code>app.message.followUp</code></td><td><code>alt+enter</code>（Windows/WSL 为 <code>ctrl+q</code>）</td><td>排队追加消息</td></tr><tr><td><code>app.message.dequeue</code></td><td><code>alt+up</code>（Windows/WSL 为 <code>alt+q</code>）</td><td>把排队的消息取回输入框</td></tr></tbody></table><h2 id="会话树" tabindex="-1">会话树 <a class="header-anchor" href="#会话树" aria-label="Permalink to &quot;会话树&quot;">​</a></h2><table tabindex="0"><thead><tr><th>动作 ID</th><th>默认按键</th><th>说明</th></tr></thead><tbody><tr><td><code>app.tree.foldOrUp</code></td><td><code>ctrl+left</code>、<code>alt+left</code></td><td>折叠当前分支段，或跳到上一段的开头</td></tr><tr><td><code>app.tree.unfoldOrDown</code></td><td><code>ctrl+right</code>、<code>alt+right</code></td><td>展开当前分支段，或跳到下一段开头/分支末尾</td></tr><tr><td><code>app.tree.editLabel</code></td><td><code>shift+l</code></td><td>编辑选中节点的标签</td></tr><tr><td><code>app.tree.toggleLabelTimestamp</code></td><td><code>shift+t</code></td><td>显示/隐藏标签时间</td></tr><tr><td><code>app.tree.filter.default</code></td><td><code>ctrl+d</code></td><td>过滤器：默认视图</td></tr><tr><td><code>app.tree.filter.noTools</code></td><td><code>ctrl+t</code></td><td>过滤器：隐藏工具结果</td></tr><tr><td><code>app.tree.filter.userOnly</code></td><td><code>ctrl+u</code></td><td>过滤器：只看用户消息</td></tr><tr><td><code>app.tree.filter.labeledOnly</code></td><td><code>ctrl+l</code></td><td>过滤器：只看带标签的条目</td></tr><tr><td><code>app.tree.filter.all</code></td><td><code>ctrl+a</code></td><td>过滤器：显示全部</td></tr><tr><td><code>app.tree.filter.cycleForward</code></td><td><code>ctrl+o</code></td><td>向前循环过滤器</td></tr><tr><td><code>app.tree.filter.cycleBackward</code></td><td><code>shift+ctrl+o</code></td><td>向后循环过滤器</td></tr></tbody></table><h2 id="循环模型选择器" tabindex="-1">循环模型选择器 <a class="header-anchor" href="#循环模型选择器" aria-label="Permalink to &quot;循环模型选择器&quot;">​</a></h2><p>在 <code>/scoped-models</code> 打开的选择器中使用。</p><table tabindex="0"><thead><tr><th>动作 ID</th><th>默认按键</th><th>说明</th></tr></thead><tbody><tr><td><code>app.models.enableAll</code></td><td><code>ctrl+a</code></td><td>启用全部模型（或当前搜索匹配的全部）</td></tr><tr><td><code>app.models.clearAll</code></td><td><code>ctrl+x</code></td><td>清除全部模型（或当前搜索匹配的全部）</td></tr><tr><td><code>app.models.toggleProvider</code></td><td><code>ctrl+p</code></td><td>切换当前服务商的所有模型</td></tr><tr><td><code>app.models.reorderUp</code></td><td><code>alt+up</code></td><td>在循环顺序中上移</td></tr><tr><td><code>app.models.reorderDown</code></td><td><code>alt+down</code></td><td>在循环顺序中下移</td></tr></tbody></table><h2 id="nek-扩展" tabindex="-1">nek 扩展 <a class="header-anchor" href="#nek-扩展" aria-label="Permalink to &quot;nek 扩展&quot;">​</a></h2><table tabindex="0"><thead><tr><th>按键</th><th>说明</th><th>配置位置</th></tr></thead><tbody><tr><td><code>alt+m</code></td><td>在 Agent 和 Plan 模式之间切换</td><td><code>nek.yaml</code> 的 <code>plan.shortcut</code></td></tr></tbody></table>`,42)])])}const b=d(r,[["render",a]]);export{u as __pageData,b as default};
